-- S95C Atlas Flavor Intelligence: curated seed (GENERATED, do not edit by hand).
--
-- Generated by `node scripts/build_flavor_seed.mjs` from data/flavor/sources.json,
-- ingredients.json, preparations.json, pairings.json and item-links.json.
-- `node scripts/build_flavor_seed.mjs --check` fails when this file is stale.
--
-- * Ids are md5 uuids of stable keys ('flavor:<slug>', 'flavor-prep:<slug>',
--   'flavor-edge:<a>|<a_prep>|<b>|<b_prep>|<relation>|<evidence>'), so a replay
--   produces the same ids. Every insert is an upsert: an unchanged row is left
--   alone, a changed curated row is updated and its version bumped.
-- * All evidence here is `culinary` from provider `atlas_curated` (Atlas-authored
--   from general culinary knowledge; draft, needs human review). Nothing is
--   labelled scientific. atlas_learned evidence is computed at runtime from the
--   venue's own recipes and is not stored here.
-- * Item links: only for inventory items that exist (where exists on
--   public.inventory_items, a read). On an empty database no link is inserted.
--   A link a manager has reviewed (reviewed_at set) is never overwritten.
-- * No statement writes to inventory, recipes, suppliers, stock, menus or
--   purchasing tables.

-- ------------------------------------------------------------------ sources
insert into atlas_private.flavor_sources (id, name, url, license, commercial_use, attribution, verdict, notes) values
  ('ahn_2011_flavor_network', 'Ahn et al. 2011, Flavor network and the principles of food pairing', 'https://doi.org/10.1038/srep00196', 'CC BY-NC-SA 3.0', false, 'Required', 'do_not_ingest', 'Non-commercial share-alike; recipe portion scraped from third-party sites. Finding may be cited as background only.'),
  ('atlas_curated', 'Atlas curated culinary knowledge', null, 'Atlas-owned (proprietary to the Atlas deployment)', true, null, 'use', 'Canonical ingredients, aroma/taste vectors, preparations and culinary pairing edges hand-authored by Atlas from general culinary and bartending knowledge. Not derived from any external dataset. Draft, needs human review (seed 0.1.0).'),
  ('atlas_learned', 'VÁ BAR recipes in Atlas (co-occurrence)', null, 'Tenant-owned data', true, null, 'use', 'atlas_learned evidence: ingredient co-occurrence in the venue''s own recipes, computed at request time by the atlas-ai Edge Function. Tenant-scoped; never shared across tenants without consent.'),
  ('culinary_reference_books', 'Published culinary reference books (e.g. The Flavor Bible, The Flavour Thesaurus)', null, 'Copyrighted compilations', false, null, 'do_not_ingest', 'Their lists are not transcribed; overlap with common culinary facts is expected.'),
  ('culinarydb', 'CulinaryDB (CoSyLab)', 'https://cosylab.iiitd.edu.in/culinarydb/', 'No licence found', false, null, 'do_not_ingest', 'Built from scraped sites; licence unknown.'),
  ('flavordb', 'FlavorDB / FlavorDB2 (IIIT-Delhi CoSyLab)', 'https://cosylab.iiitd.edu.in/flavordb2/', 'Free for non-commercial use only', false, 'Cite the FlavorDB papers', 'do_not_ingest', 'Non-commercial. No molecule or pairing data from it is in Atlas.'),
  ('flavornet', 'Flavornet (Acree & Arn, Cornell)', 'https://www.flavornet.org', 'No open licence (author copyright)', false, null, 'do_not_ingest', 'May be cited as literature only.'),
  ('foodb', 'FooDB', 'https://foodb.ca', 'CC BY-NC 4.0', false, 'Required', 'do_not_ingest', 'Non-commercial licence.'),
  ('foodon', 'FoodOn ontology', 'https://github.com/FoodOntology/foodon', 'CC BY 4.0', true, 'Required: credit FoodOn and include the licence', 'use_with_attribution', 'Allowed for an optional foodon_id crosswalk and process terms. No data ingested in the MVP seed.'),
  ('foodpairing', 'Foodpairing', 'https://www.foodpairing.com', 'Proprietary, commercial', false, null, 'do_not_ingest', 'Do not ingest, scrape, reconstruct or imitate its data, graphs or visuals.'),
  ('good_scents', 'The Good Scents Company', 'http://www.thegoodscentscompany.com', 'Copyright; permission to reproduce required', false, null, 'do_not_ingest', 'Staff may consult it; nothing is copied.'),
  ('kaggle_cocktail_datasets', 'Kaggle cocktail datasets', null, 'Varies; often unknown or CC BY-NC', false, null, 'do_not_ingest', 'Often re-uploads of TheCocktailDB or publisher content. Classic ratios are authored by Atlas instead.'),
  ('langual', 'LanguaL', 'https://www.langual.org', 'No clear licence found', false, null, 'do_not_ingest', 'Until written terms are obtained.'),
  ('open_food_facts', 'Open Food Facts', 'https://world.openfoodfacts.org/data', 'ODbL 1.0 (database), DbCL 1.0 (contents), CC BY-SA (images)', true, 'Required', 'needs_legal_review', 'Share-alike for public derivative databases; would need a separate bounded table. Not used in the MVP.'),
  ('pubchem', 'PubChem (NCBI)', 'https://pubchem.ncbi.nlm.nih.gov', 'Public domain for NCBI core data; depositor annotations carry their own terms', true, 'Citation requested', 'use_with_attribution', 'Core compound ids only, for a future scientific layer; depositor annotations need legal review. No data ingested in the MVP seed.'),
  ('recipe1m', 'Recipe1M / Recipe1M+ (MIT CSAIL)', 'http://im2recipe.csail.mit.edu', 'Non-commercial research and education only', false, null, 'do_not_ingest', 'Non-commercial terms of use.'),
  ('recipedb', 'RecipeDB (CoSyLab)', 'https://cosylab.iiitd.edu.in/recipedb/', 'CC BY-NC-SA 3.0', false, 'Required', 'do_not_ingest', 'Non-commercial.'),
  ('recipenlg_kaggle_recipes', 'RecipeNLG and Kaggle recipe dumps', null, 'Varies; scraped third-party content', false, null, 'do_not_ingest', 'Unclear licences.'),
  ('thecocktaildb', 'TheCocktailDB', 'https://www.thecocktaildb.com', 'Proprietary API (paid key for commercial use)', false, 'Per their terms', 'needs_legal_review', 'Storing their data as Atlas evidence is not granted; not used in the MVP.'),
  ('usda_fdc', 'USDA FoodData Central', 'https://fdc.nal.usda.gov', 'Public domain / CC0 1.0', true, 'Citation requested', 'use_with_attribution', 'Allowed for nutrition enrichment only (no flavour data). No data ingested in the MVP seed.'),
  ('wikidata', 'Wikidata', 'https://www.wikidata.org', 'CC0 1.0', true, 'Not required (courtesy)', 'use', 'Allowed for cross-reference ids and Icelandic/English labels; never flavour evidence. No data ingested in the MVP seed.')
on conflict (id) do update set name = excluded.name, url = excluded.url, license = excluded.license,
  commercial_use = excluded.commercial_use, attribution = excluded.attribution, verdict = excluded.verdict, notes = excluded.notes
where (atlas_private.flavor_sources.name, atlas_private.flavor_sources.url, atlas_private.flavor_sources.license,
       atlas_private.flavor_sources.commercial_use, atlas_private.flavor_sources.attribution,
       atlas_private.flavor_sources.verdict, atlas_private.flavor_sources.notes)
  is distinct from (excluded.name, excluded.url, excluded.license, excluded.commercial_use, excluded.attribution,
       excluded.verdict, excluded.notes);

-- ------------------------------------------------------------------ preparations
insert into atlas_private.flavor_preparations (id, slug, name, taste_shift, aroma_shift, texture, notes) values
  ('e42fde53-f09f-adff-508e-1f655a3dd175'::uuid, 'brewed', 'Brewed hot', '{"astringency":1,"bitter":1}'::jsonb, '{"roasted":0.1}'::jsonb, 'thin', 'Hot extraction of coffee, tea or herbs; more aromatics and tannin.'),
  ('2b679fa9-9073-5544-07a1-bed8158b88e4'::uuid, 'caramelised', 'Caramelised', '{"bitter":1,"sour":-1,"sweet":1}'::jsonb, '{"caramel_sweet":0.5,"roasted":0.2}'::jsonb, 'stickier', 'Sugar taken to caramel; fresh fruit notes recede.'),
  ('68a556ff-bb8d-803d-602b-36394b831943'::uuid, 'carbonated', 'Carbonated', '{"sour":1}'::jsonb, '{"citrus":0.1}'::jsonb, 'sparkling', 'Carbonic bite lifts citrus and bitterness and releases aroma.'),
  ('57538032-6604-e976-448c-bafded180d9f'::uuid, 'clarified', 'Clarified', '{"astringency":-2,"bitter":-1}'::jsonb, '{"dairy_creamy":0.1}'::jsonb, 'thin, clear', 'Agar, milk-wash or centrifuge; cloudy aromas drop, shelf-stable.'),
  ('2f4b8eda-66f7-9edb-a889-959f5bec665e'::uuid, 'cold-brew', 'Cold brew', '{"bitter":-1,"sour":-1}'::jsonb, '{"caramel_sweet":0.1}'::jsonb, 'thin', 'Long cold extraction: smoother, less acidic and bitter.'),
  ('0bf5c700-6eaa-b1a6-fa8b-b18f68b80e59'::uuid, 'cordial', 'Cordial', '{"sour":2,"sweet":4}'::jsonb, '{"citrus":0.1}'::jsonb, 'syrupy', 'As a syrup with added acid; bright top notes kept.'),
  ('e18830cd-7c6b-17aa-cd62-071e58c2eb0f'::uuid, 'dehydrated', 'Dehydrated', '{"sour":1,"sweet":1}'::jsonb, '{"caramel_sweet":0.2,"earthy":0.2}'::jsonb, 'crisp', 'Top notes fade, sugars and acids concentrate; garnish or powder.'),
  ('248318a9-a0f2-3cd5-be63-d2d735b9ad36'::uuid, 'espresso', 'Espresso', '{"bitter":1}'::jsonb, '{"roasted":0.2}'::jsonb, 'crema', 'Pressure extraction: concentrated, crema foams in shaken drinks.'),
  ('93b86da4-a406-8576-5e23-3d25577ff2e9'::uuid, 'fat-wash', 'Fat wash', '{"astringency":-1,"fat":1}'::jsonb, '{"dairy_creamy":0.3,"nutty":0.2}'::jsonb, 'silkier', 'Spirit infused with a fat, chilled and strained; the fat''s aroma carries over.'),
  ('91af4f5d-2680-e03d-e247-479b08544c4b'::uuid, 'fermented', 'Fermented', '{"sour":2,"sweet":-2,"umami":1}'::jsonb, '{"fermented_funky":0.4}'::jsonb, 'fizzy when live', 'Lacto or yeast fermentation; fruit shifts towards wine-like notes.'),
  ('8e6a835b-85ab-3cee-4d11-038108faa403'::uuid, 'foam', 'Foam / whipped', '{"sweet":-1}'::jsonb, '{}'::jsonb, 'foam', 'Aroma perceived first and lighter; air dilutes perceived sweetness.'),
  ('ac388c82-f54d-4994-504c-8bb36fb6d6b6'::uuid, 'frozen', 'Frozen / blended', '{"sweet":-1}'::jsonb, '{}'::jsonb, 'slushy', 'Cold suppresses aroma (about -0.2) and sweetness; recipes need roughly 10-20% more sugar.'),
  ('78208643-36b9-6405-dce6-57d28cbc73fe'::uuid, 'grilled', 'Grilled / charred', '{"bitter":1,"sweet":1}'::jsonb, '{"caramel_sweet":0.2,"green_herbal":-0.3,"roasted":0.3,"smoky":0.3}'::jsonb, 'softer', 'Char adds smoke and roasted sugar notes; fresh green notes recede.'),
  ('011ace0f-b2d2-8500-a998-f4b6f74f1d78'::uuid, 'infusion', 'Infusion', '{"astringency":1,"bitter":1}'::jsonb, '{}'::jsonb, 'as the base liquid', 'Adds the infused ingredient''s aroma at about 0.3-0.7 depending on time; bitterness and tannin if over-extracted (tea, peel, woody spices).'),
  ('64a41ac4-d33d-bede-b247-7c8b56d7ad03'::uuid, 'juice', 'Fresh juice', '{"bitter":-1}'::jsonb, '{"citrus":-0.2}'::jsonb, 'thin', 'Loses peel aromatics, keeps fruit; sour and sweet concentrated, no pith bitterness. Citrus is best within about 4-8 hours.'),
  ('e7fce48d-b76b-f1ed-d790-24b442ef0d65'::uuid, 'muddled', 'Muddled', '{"bitter":1}'::jsonb, '{"green_herbal":0.1}'::jsonb, 'pulpy', 'Releases herb oils and juice; over-muddled herbs or peel turn green and bitter.'),
  ('b61b6366-1e1e-272b-f8e3-ed02add576e0'::uuid, 'oleo-saccharum', 'Oleo saccharum', '{"bitter":1,"sweet":5}'::jsonb, '{"citrus":0.5}'::jsonb, 'syrupy', 'Citrus peel macerated in sugar; very aromatic.'),
  ('c2ad2197-6f61-f2ce-33a0-f7c3ebca354d'::uuid, 'pickled', 'Pickled', '{"salty":2,"sour":3}'::jsonb, '{"fermented_funky":0.2}'::jsonb, 'firmer', 'Brined or vinegar-pickled; the brine itself works in savoury drinks.'),
  ('bfa3a625-5628-690e-b7bc-6c96e96d3ba0'::uuid, 'powder', 'Powder', '{"sour":1,"sweet":1}'::jsonb, '{"caramel_sweet":0.1}'::jsonb, 'powder', 'As dehydrated with fast release; rims and dusting.'),
  ('d03218d7-497b-58e9-4bc4-568921ce4763'::uuid, 'puree', 'Purée', '{"sweet":1}'::jsonb, '{}'::jsonb, 'thick', 'Whole fruit blended: body and colour, rounder than juice.'),
  ('1f8c4296-48d0-a136-391a-cf75560c429d'::uuid, 'reduction', 'Reduction', '{"alcohol":-3,"sour":1,"sweet":1,"umami":1}'::jsonb, '{"caramel_sweet":0.3}'::jsonb, 'thicker', 'Simmered down; volatile top notes drop by about 0.3.'),
  ('6f9e9f73-406a-b068-b866-860cb1247ea3'::uuid, 'roasted', 'Roasted', '{"sour":-1,"sweet":1,"umami":1}'::jsonb, '{"caramel_sweet":0.3,"green_herbal":-0.4,"nutty":0.2,"roasted":0.4,"vegetal":-0.4}'::jsonb, 'drier, concentrated', 'Dry heat concentrates sugars and adds roasted notes.'),
  ('4b3152c6-1d2a-33fe-3015-a36a21475666'::uuid, 'saline-solution', 'Saline solution', '{"bitter":-1,"salty":1}'::jsonb, '{}'::jsonb, 'drops', 'A few drops suppress bitterness and lift fruit and sweetness.'),
  ('53f86022-14f5-ea36-2df5-777d89eff1ea'::uuid, 'shrub', 'Shrub', '{"sour":4,"sweet":4}'::jsonb, '{"fermented_funky":0.2}'::jsonb, 'syrupy', 'Fruit, sugar and vinegar; shelf-stable acidity for spirit-free drinks.'),
  ('539daae4-b291-0e51-6bf4-d0099908e71b'::uuid, 'smoked', 'Smoked', '{"bitter":1}'::jsonb, '{"smoky":0.5,"woody":0.2}'::jsonb, 'unchanged', 'Aroma-dominant: treat as one step more intense.'),
  ('452d0fa2-92d2-3929-91cf-8feb7228a48e'::uuid, 'syrup', 'Syrup', '{"sweet":4}'::jsonb, '{"caramel_sweet":0.1}'::jsonb, 'syrupy', 'Carries the ingredient''s aroma at roughly half to four fifths of fresh; sweet towards 5. 1:1 about 0.6 g sugar per ml, 2:1 about 0.9 g per ml.'),
  ('1f70d87f-04e8-86bc-dc26-083b9e323e55'::uuid, 'tincture', 'Tincture', '{"alcohol":5}'::jsonb, '{}'::jsonb, 'dash', 'Concentrated extract used in drops or dashes; intensity 5.'),
  ('d1a7a42b-5ccd-ded7-6988-e0da30c62f6b'::uuid, 'toasted', 'Toasted', '{"bitter":1}'::jsonb, '{"nutty":0.3,"roasted":0.3}'::jsonb, 'crisper', 'Nuts, spices, seeds or coconut; volatile top notes drop, bitterness if taken dark.'),
  ('9cbb6edc-b326-ef8b-dea4-0d3a49c0cb1f'::uuid, 'zest', 'Zest / expressed peel', '{"bitter":1}'::jsonb, '{"bitter_botanical":0.1,"citrus":0.3,"floral":0.3}'::jsonb, 'aromatic oil', 'Peel oils only: aroma without liquid volume; bitterness only if pith is included.')
on conflict (slug) do update set name = excluded.name, taste_shift = excluded.taste_shift,
  aroma_shift = excluded.aroma_shift, texture = excluded.texture, notes = excluded.notes
where (atlas_private.flavor_preparations.name, atlas_private.flavor_preparations.taste_shift,
       atlas_private.flavor_preparations.aroma_shift, atlas_private.flavor_preparations.texture,
