on conflict (id) do update set strength = excluded.strength, aroma_score = excluded.aroma_score, taste_score = excluded.taste_score, texture_score = excluded.texture_score, contexts = excluded.contexts, provider = excluded.provider, confidence = excluded.confidence, explanation = excluded.explanation,
  version = atlas_private.flavor_edges.version + 1
where (atlas_private.flavor_edges.strength, atlas_private.flavor_edges.aroma_score, atlas_private.flavor_edges.taste_score, atlas_private.flavor_edges.texture_score, atlas_private.flavor_edges.contexts, atlas_private.flavor_edges.provider, atlas_private.flavor_edges.confidence, atlas_private.flavor_edges.explanation)
  is distinct from (excluded.strength, excluded.aroma_score, excluded.taste_score, excluded.texture_score, excluded.contexts, excluded.provider, excluded.confidence, excluded.explanation);

